        program,
        ids: Vec::new(),
        liveness: Vec::new(),
        origins: Vec::new(),
        _scratch: Scratch::default(),
    };
    let payer = Payer::current();
    payer.reserve(0)?;
    for plan in plans {
        append(&mut storage, plan, payer)?;
